package com.simpletoob.app;
import android.app.job.*;
import android.content.*;
import android.net.*;
import android.os.*;
import java.util.*;
import java.util.concurrent.*;
/** One coordinator, three independent account-read workers, and the existing serialized disk worker. */
public final class ImportManager {
    static final int JOB_ID=4105;private final java.util.concurrent.atomic.AtomicLong dataVersion=new java.util.concurrent.atomic.AtomicLong();public long version(){return dataVersion.get();}
    private final SimpleToobApp app;private final Handler main=new Handler(Looper.getMainLooper());
    private final CopyOnWriteArrayList<Runnable> listeners=new CopyOnWriteArrayList<>();
    private long lastIdentityAttempt;private String lastIdentityScope="";
    private volatile String progress="",progressProfile="";private volatile Future<?> active;
    private volatile List<Future<?>> children=Collections.synchronizedList(new ArrayList<>());private final ThreadLocal<List<Future<?>>> runChildren=new ThreadLocal<>();
    ImportManager(SimpleToobApp a){app=a;}
    private String prefix(){return "import."+app.sessions.profile()+".";}
    public boolean launch(String kind){return app.prefs.flag(prefix()+kind+".launch",false);}
    public int minutes(String kind){return app.prefs.number(prefix()+kind+".minutes",0);}
    public void launch(String kind,boolean on){app.prefs.put(prefix()+kind+".launch",on);configure();}
    public void interval(String kind,int minutes){ImportPolicy.intervalMillis(minutes);app.prefs.put(prefix()+kind+".minutes",minutes);configure();}
    public boolean mirror(){return app.prefs.flag(prefix()+"mirror",false);}
    public void mirror(boolean on){app.prefs.put(prefix()+"mirror",on);}
    public boolean unmetered(){return app.prefs.flag(prefix()+"unmetered",false);}
    public void unmetered(boolean on){app.prefs.put(prefix()+"unmetered",on);configure();}
    public long last(String kind){return app.prefs.data.getLong(prefix()+kind+".last."+app.sessions.owner(),0);}
    private long lastAttempt(String kind){return app.prefs.data.getLong(prefix()+kind+".attempt."+app.sessions.owner(),0);}
    private long lastRun(String kind){return Math.max(last(kind),lastAttempt(kind));}
    public String status(){if(!app.sessions.present())return "Signed out · automatic imports paused";return progressProfile.equals(app.sessions.profile())&&!progress.isEmpty()?progress:app.prefs.text(prefix()+"status",app.sessions.present()?"Ready to import":"Signed out · automatic imports paused");}
    public boolean running(){Future<?> f=active;return f!=null&&!f.isDone();}
    public void listen(Runnable r){listeners.addIfAbsent(r);}public void unlisten(Runnable r){listeners.remove(r);}
    private void changed(){main.post(()->{for(Runnable r:listeners)r.run();});}
    private void state(String profile,String message){progressProfile=profile;progress=message;app.prefs.put("import."+profile+".status",message);changed();}
    public void sessionChanged(){cancel();dataVersion.incrementAndGet();configure();changed();}
    public void cancel(){Future<?> f=active;boolean wasRunning=f!=null&&!f.isDone();if(f!=null)f.cancel(true);synchronized(children){for(Future<?> c:children)c.cancel(true);children.clear();}active=null;if(wasRunning)state(progressProfile,"Import stopped; completed local copies kept");}
    public void configure(){JobScheduler jobs=app.getSystemService(JobScheduler.class);int interval=ImportPolicy.minimum(minutes("subs"),minutes("lists"));if(!automaticAllowed()||interval==0){jobs.cancel(JOB_ID);return;}JobInfo old=jobs.getPendingJob(JOB_ID);String profile=app.sessions.profile(),revision=app.sessions.revision();int network=unmetered()?JobInfo.NETWORK_TYPE_UNMETERED:JobInfo.NETWORK_TYPE_ANY;
        if(old!=null&&old.getIntervalMillis()==ImportPolicy.intervalMillis(interval)&&profile.equals(old.getExtras().getString("profile"))&&revision.equals(old.getExtras().getString("revision"))&&old.getNetworkType()==network)return;
        PersistableBundle extras=new PersistableBundle();extras.putString("profile",profile);extras.putString("revision",revision);jobs.schedule(new JobInfo.Builder(JOB_ID,new ComponentName(app,ImportJobService.class)).setPeriodic(ImportPolicy.intervalMillis(interval)).setRequiredNetworkType(network).setPersisted(true).setExtras(extras).build());
    }
    public boolean automaticAllowed(){return app.sessions.present()&&!app.sessions.revision().equals(app.prefs.text(prefix()+"auth_pause",""));}
    public void foreground(){configure();if(!automaticAllowed())return;refreshIdentity();boolean subs=launch("subs"),lists=launch("lists");long now=System.currentTimeMillis();subs|=ImportPolicy.due(true,minutes("subs"),lastRun("subs"),now);lists|=ImportPolicy.due(true,minutes("lists"),lastRun("lists"),now);if(subs||lists)start(subs,lists,null);}
    private void refreshIdentity(){long now=System.currentTimeMillis();if(app.sessions.verified()&&!app.sessions.avatar().isEmpty()||(app.sessions.profile()+app.sessions.revision()).equals(lastIdentityScope)&&now-lastIdentityAttempt<30*60000L)return;lastIdentityAttempt=now;lastIdentityScope=app.sessions.profile()+app.sessions.revision();String profile=app.sessions.profile(),revision=app.sessions.revision();try{app.importReads.execute(()->{try{reader(profile,revision).verify();check(profile,revision);dataVersion.incrementAndGet();changed();}catch(Exception ignored){Diagnostics.record("account image refresh unavailable");}});}catch(RejectedExecutionException ignored){}}
    public void due(Runnable done){long now=System.currentTimeMillis();boolean subs=ImportPolicy.due(automaticAllowed(),minutes("subs"),lastRun("subs"),now),lists=ImportPolicy.due(automaticAllowed(),minutes("lists"),lastRun("lists"),now);if(subs||lists)start(subs,lists,done);else if(done!=null)done.run();}
    private void check(String profile,String revision)throws Exception{if(Thread.currentThread().isInterrupted()||!app.sessions.present()||!profile.equals(app.sessions.profile())||!revision.equals(app.sessions.revision()))throw new InterruptedException("Account changed; import stopped");}
    private YoutubeWebClient reader(String profile,String revision){return new YoutubeWebClient(app.sessions,app.prefs).pin(profile,revision);}
    private <T> Future<T> read(Callable<T> callable){Future<T> f=app.importReads.submit(callable);runChildren.get().add(f);return f;}
    private <T> T disk(String profile,String revision,Callable<T> callable)throws Exception{return app.disk.submit(()->{check(profile,revision);LibraryStore store=app.library;android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{T result=callable.call();check(profile,revision);db.setTransactionSuccessful();return result;}finally{db.endTransaction();}}).get();}
    public synchronized void start(boolean subs,boolean playlists,Runnable done){if(running()){if(done!=null)done.run();return;}if(!app.sessions.present()){state(app.sessions.profile(),"Signed out · imports paused");if(done!=null)done.run();return;}
        String profile=app.sessions.profile(),revision=app.sessions.revision(),base="import."+profile+".";LibraryStore library=app.library;boolean mirror=mirror();
        List<Future<?>> tasks=Collections.synchronizedList(new ArrayList<>());children=tasks;try{active=app.importControl.submit(()->{runChildren.set(tasks);try{check(profile,revision);ConnectivityManager network=app.getSystemService(ConnectivityManager.class);if(unmetered()&&network.isActiveNetworkMetered())throw new Exception("Waiting for an unmetered connection");long attemptedAt=System.currentTimeMillis();String initialOwner=app.sessions.owner();if(subs)app.prefs.data.edit().putLong(base+"subs.attempt."+initialOwner,attemptedAt).apply();if(playlists)app.prefs.data.edit().putLong(base+"lists.attempt."+initialOwner,attemptedAt).apply();state(profile,"Checking the signed-in account…");try{reader(profile,revision).verify();app.prefs.put(base+"auth_pause","");configure();}catch(Exception auth){String text=auth.getMessage()==null?"":auth.getMessage();if(text.contains("HTTP 401")||text.contains("HTTP 403")){app.prefs.put(base+"auth_pause",revision);configure();}throw auth;}check(profile,revision);String owner=app.sessions.owner();if(owner.isEmpty())throw new Exception("YouTube did not expose a stable account/channel identity. Existing local items were kept.");if(subs)app.prefs.data.edit().putLong(base+"subs.attempt."+owner,attemptedAt).apply();if(playlists)app.prefs.data.edit().putLong(base+"lists.attempt."+owner,attemptedAt).apply();
            Future<List<AccountCollections.Channel>> channels=subs?read(()->fetchChannels(profile,revision)):null;
            Future<List<YoutubeWebClient.Entry>> index=playlists?read(()->reader(profile,revision).accountPlaylists()):null;
            int channelCount=0,playlistCount=0,failedPlaylists=0;boolean subscriptionsFailed=false;
            if(channels!=null){try{List<AccountCollections.Channel> rows=channels.get();check(profile,revision);disk(profile,revision,()->{library.importSubscriptions(owner,rows,mirror);return true;});check(profile,revision);app.prefs.data.edit().putLong(base+"subs.last."+owner,System.currentTimeMillis()).apply();channelCount=rows.size();state(profile,"Imported "+channelCount+" subscriptions");}catch(ExecutionException failure){check(profile,revision);subscriptionsFailed=true;state(profile,"Subscriptions could not refresh; existing local copies kept");}}
            if(index!=null){List<YoutubeWebClient.Entry> entries=index.get();Set<String> remoteIds=new HashSet<>();for(YoutubeWebClient.Entry e:entries)remoteIds.add(e.id);for(int at=0;at<entries.size();at+=3){check(profile,revision);List<Future<PlaylistSnapshot>> batch=new ArrayList<>();for(int j=at;j<Math.min(entries.size(),at+3);j++){YoutubeWebClient.Entry entry=entries.get(j);batch.add(read(()->fetchPlaylist(profile,revision,entry)));}for(Future<PlaylistSnapshot> f:batch){PlaylistSnapshot snapshot;try{snapshot=f.get();}catch(ExecutionException failed){check(profile,revision);failedPlaylists++;state(profile,"Some playlists could not refresh; existing local copies kept");continue;}check(profile,revision);disk(profile,revision,()->{library.importPlaylist(owner,snapshot.entry,snapshot.rows);return true;});remoteIds.add(snapshot.entry.id);playlistCount++;state(profile,"Imported "+playlistCount+" / "+entries.size()+" playlists");}}
                if(failedPlaylists==0){disk(profile,revision,()->{library.finishPlaylistImport(owner,remoteIds,mirror);return true;});check(profile,revision);app.prefs.data.edit().putLong(base+"lists.last."+owner,System.currentTimeMillis()).apply();}}
            check(profile,revision);state(profile,"Import finished · "+channelCount+" subscriptions · "+playlistCount+" playlists"+(subscriptionsFailed?" · subscriptions could not refresh":"")+(failedPlaylists==0?"":" · "+failedPlaylists+" could not refresh; previous copies kept"));
        }catch(Exception e){if(profile.equals(app.sessions.profile())&&revision.equals(app.sessions.revision())){Throwable cause=e instanceof ExecutionException&&e.getCause()!=null?e.getCause():e;state(profile,Thread.currentThread().isInterrupted()?"Import stopped; completed local copies kept":cause.getMessage()==null?"Import failed; existing local items kept":cause.getMessage());}}finally{synchronized(tasks){for(Future<?> f:tasks)if(!f.isDone())f.cancel(true);tasks.clear();}runChildren.remove();dataVersion.incrementAndGet();changed();if(done!=null)main.post(done);}});}catch(RejectedExecutionException e){state(profile,"Import workers are busy. Try again shortly.");if(done!=null)done.run();}
    }
    private List<AccountCollections.Channel> fetchChannels(String profile,String revision)throws Exception{YoutubeWebClient web=reader(profile,revision);LinkedHashMap<String,AccountCollections.Channel> rows=new LinkedHashMap<>();Set<String> seen=new HashSet<>();String next="";for(int page=0;page<500;page++){check(profile,revision);YoutubeWebClient.CollectionResult result=web.collection("subscriptions",next);for(AccountCollections.Channel c:result.channels)rows.put(c.url,c);next=result.next;if(next.isEmpty())return new ArrayList<>(rows.values());if(!seen.add(next))throw new Exception("YouTube repeated a subscription page; local subscriptions kept");}throw new Exception("Subscription import exceeded its page limit; local subscriptions kept");}
    private static final class PlaylistSnapshot{final AccountCollections.Playlist entry;final List<Video> rows;PlaylistSnapshot(AccountCollections.Playlist e,List<Video> r){entry=e;rows=r;}}
    private PlaylistSnapshot fetchPlaylist(String profile,String revision,YoutubeWebClient.Entry entry)throws Exception{YoutubeWebClient web=reader(profile,revision);List<Video> rows=new ArrayList<>();Set<String> pages=new HashSet<>(),ids=new HashSet<>();String next="";for(int page=0;page<500;page++){check(profile,revision);YoutubeRepository.PlaylistResult result=web.playlist(entry.id,next);for(Video v:result.page.videos)if(ids.add(v.id))rows.add(v);if(rows.size()>50000)throw new Exception("Playlist exceeds 50,000 playable videos; existing local copy kept");next=result.page.next;if(next.isEmpty())return new PlaylistSnapshot(new AccountCollections.Playlist(entry.id,entry.title),rows);if(!pages.add(next))throw new Exception("YouTube repeated a playlist page; existing local copy kept");}throw new Exception("Playlist page limit reached; existing local copy kept");}
}
